function flatten(value) {
  const result = [];
  const stack = [value];

  while (stack.length > 0) {
    const current = stack.pop();

    if (Array.isArray(current)) {
      for (let i = current.length - 1; i >= 0; i -= 1) {
        stack.push(current[i]);
      }
    } else {
      result.push(current);
    }
  }

  return result.reverse();
}
